INSERT INTO `manuscripts`
(`title`, `authors`, `abstract`, `email`, `year`, `volume`, `issue`, `pages`, `category`, `pdf_upload`)
VALUES
  ('Editorial Comment', 'Dr. H.O. Otamere', '', 'otaharri2012@gmail.com', 2022, 1, '1', '1', '', 'uploads/AAUJMR_V1_I1/Editorial comment.pdf'),
  ('Cytoprotective Action of Folic Acid Supplementation in Experimentally-Induced Gastric Ulceration in Rats', 'Otamere H.O., Orji J.C., Odiase D.E.', 'The effect of folic acid (2 mg/kg oral) on experimentally induced gastric ulcers was investigated by evaluating gastric ulcer indices, acid secretion and gastric biochemical levels of protein, markers of oxidative stress and antioxidant, mucin and nitric-oxide in adult male Wistar rats. Twenty rats were divided into 4 groups as indomethacin ulcer control, folic acid -treated + indomethacin ulcer, pyloric ligation control and folic acid -treated + pyloric ligation ulcer. Rats treated with the drug of study were pre-treated for 6 days and one hour before ulcer induction. The acute gastric ulcer models used were indomethacin induced and pylorus ligation and were performed following standard laboratory methods. Four hours after ulcer induction, laparectomy was performed and the stomach harvested for macroscopic and acid content studies and biochemical analysis. The data was analyzed using statistical tools from SPSS (version 21) and “student t test” was performed at p<0.05 level of significance. Folic acid treatment resulted in decreased in ulcer index with a protective ratio of 55.56%, non-significant increase in gastric acidity, increase in gastric protein (1.07±0.06 vs 1.28±0.13; p>0.05), nitric oxide (120.33±6.67 vs 151.17±28.16; p<0.05), mucin content (36.20±1.99 vs 36.89±4.29; p>0.05) and GSH levels (2.38±0.40 vs 2.51±0.18; p>0.05) and decrease in MDA (1.16±0.001 vs 0.59±0.003; p>0.05) compare to control in the indomethacin induced ulcer model. Folic acid treatment in the pyloric ligation ulcer model resulted in a significant decrease in ulcer index with a protective ratio of 60.00%, non-significant increase in gastric acidity, mucin content (38.58±3.03 vs 39.55±0.84; p>0.05), but decrease in gastric MDA (1.19±0.01 vs 0.89±0.001; p>0.05), GSH (2.49±0.29 vs 2.36±0.23; p>0.05), nitric oxide (145.89±14.86 vs 106.86±7.64) and protein (1.31±0.01 vs 1.21±0.01) compared to control. The antiulcer activity of folic acid may be attributed to its stimulatory effect on gastric mucin concentration and inhibitory effect on oxidative stress.', 'otaharri2012@gmail.com', 2022, 1, '1', '2-9', '', 'uploads/AAUJMR_V1_I1/Paper 1. Otamere et al AAUJMR 1(1) 2-9.pdf'),
  ('Tissular Responses in Rat Lungs Following Acute Gasoline Vapour Inhalation', 'Ujaddughe O.M., Akpamu U., Blackies H.O.T., Omole O.B., Irorere I.D., Efoghe J., Afolabi S.', 'With the increasing global population and the dependence of human activities on crude oil and crude oil products, there is a resultant increase in crude production, as well as increased exposure to these products. The major route of human exposure has been via inhalation and skin contact. There are reported effects of COP exposure on organ/system, but evidence of lungs tissular response are rare. It is the objective of this study to investigate the tissular response of the lungs to acute inhalation of gasoline vapour using Wistar rats. Fifteen male Wistar rats (80–120g) were divided to 3 groups: a control and two test groups exposed to gasoline vapour for 1 and 3 hours respectively for 6 days in an exposure chamber. They were maintained under standard laboratory conditions and fed rat chow and clean water ad libitum throughout the experiment. Body weight was determined every other day and at the end of 6 days of exposure, blood samples were collected and the lungs harvested for weight determination, and biochemical and histological evaluations. Statistical analysis (ANOVA and LSD post-hoc) was done using SPSS (version 20) and p<0.05 was considered significant. The results showed acute inhalation of gasoline vapour to cause an increase in percentage weight gain, Nitric oxide level, Na+-K+- and H+-K+ pump activities, but decreased GSH and relative weight of the lungs. Histologically, the exposure to gasoline resulted in emphysematous alveoli space and desquamated airway. These results imply that exposure to acute inhalation of gasoline vapour may decrease respiratory efficiency through inhibited mucus secretion and antioxidant and stimulated nitric oxide and Na +-K+- ATPase activities to cause dysfunction and distorted lungs tissue histology.', 'uwaifoh.akpmu@fuoye.edu.ng', 2022, 1, '1', '10-19', '', 'uploads/AAUJMR_V1_I1/Paper 2. Ujaddughe et al AAUJMR 1(1) 10-19.pdf'),
  ('Dermatoglyphic Patterns and Academic Performance Among Primary School Pupils in Ekpoma, Nigeria', 'Anyanwu L.C., Owoyemi B.A., Ishola Z.T.', 'Finger/palm dermatoglyphics developed same time as the brain and both have genetic dispensation. Could brain intellectual function leave traces on the fingers/palms? This study, assesses the relationship between dermatoglyphic patterns and academic performance. Three years academic results of Ambrose Alli University Primary School, Ekpoma, were used to sample pupils into those with high or poor academic performance. Finger and palm prints were obtained and analyzed. The data were subjected to descriptive statistics and chi-square test using SPSS (version 21). Pupils with high academic performance were significantly (P<0.05) more likely to have whorl fingerprint in the right index (X2 = 8.023), left index (X2 = 4.250) and ring fingers (X2 = 4.250) with females more likely represented in the left index (X2 = 9.093) and ring fingers (X2 = 6.982). According to the number of Primary creases, Intersections of the primary crease, and Complete transverse Crease (PIC) model of classification, the 300 PIC was more likely to occur in the left hand of high academic performing pupils (X2 = 4.800, P<0.05) with significant difference (X 2 = 4.500; p<0.05) in the male. Pupils with high academic performance were more likely to have 3 points origin in the left palm (4.800; p<0.05). Academic performance showed a relationship with finger and palm prints and varies with gender. The presence of whorl in the right index left index, and ring fingers, left hand 300PIC, and 3 points origin of primary palm creases maybe determinants for high academic performance.', 'proflukeanyanwu@gmail.com', 2022, 1, '1', '20-30', '', 'uploads/AAUJMR_V1_I1/paper 3. Anyanwu et al AAUJMR 1(1) 20-30.pdf'),
  ('A Systematic Review of Antimicrobial Self-Medication in Nigeria', 'Iribhogbe O.I.', 'Antimicrobial self-medication (ASM) has triggered a major global health crisis due to the associated risk of antimicrobial drug resistance. There is a high prevalence of ASM in low and middle-income countries including Nigeria, hence the review was undertaken to evaluate its impact and consequences. The study entails a systematic review of 18 research articles on antimicrobial self-medication in Nigeria using search engines such as Google Scholar, Medline, Hinari, PubMed, Ebscohost, Embase, and Scopus. A two-stage approach was used in selecting the articles using specifically defined inclusion and exclusion criteria. A schematic flow-chart was developed as recommended by the Prisma statement on conducting systematic reviews and meta-analysis and results were presented as proportions in tables and charts. The review showed that the prevalence of ASM in Nigeria was 51.4% with antimicrobials such as amoxicillin + clavulanic acid (66.7%), ampicillin + cloxacillin (55.6%), ampicillin (44.4%), metronidazole (27.8%), and ciprofloxacin (27.8%) topping the list as the most frequently misused antimicrobials in Nigeria. The burden of antimicrobial self-medication is high and it may have a grave impact on healthcare delivery both in Nigeria and globally. The adoption of a multisectoral approach as a public health intervention strategy will greatly help in mitigating the emerging risk of ASM in the country.', 'osedeignis@gmail.com', 2022, 1, '1', '31-38', '', 'uploads/AAUJMR_V1_I1/paper 4. Iribhogbe AAUJMR 1(1) 31-38.pdf'),
  ('The Effect of Garcinia Kola on Some Serum Oxidative Stress and Anabolic-Catabolic Biological Markers in Male Wistar Rats', 'Osifo C.U., Iyawe V.I.', 'This study investigates the effect of Garcinia kola (G. kola) seed on some serum oxidative stress and anabolic- catabolic biological markers in rat model. Daily varying doses of crude G. kola seed (1000mg/kg (group B), 1200mg/kg (group C) and 1400mg/kg (group D)) was mixed with feed of rats (180-200g) while the control (group A) had feed only. At the end of seven days on these diets, blood sample was obtained for estimation of serum protein, Malondialdehyde-MDA, Superoxide dismutase-SOD, and Catalase-CAT, testosterone and cortisol. The data were subjected to statistical analysis (ANOVA) and LSD post-hoc test at p<0.05 using SPSS (version 20). The results revealed increased body weight (p>0.05), dose dependent increased in serum CAT (220.04±21.19; 342.29±29.95; 456.48±31.33l and 485.04±32.47 U/mg protein), SOD (17.00±2.17; 20.19±2.17; 26.24±1.59; 33.67±3.85 U/mg protein) and testosterone (4.12±0.77; 5.52±1.12; 5.96±01.07; 6.48±1.35 ng/ml) by graded doses of G. kola. On the other hand, there was dose dependent non-significant decrease (p>0.05) in serum MDA (4.77±0.47, 4.02±0.55, 3.62±0.64 and 3.01±0.15 U/ml) and protein (3.45±0.31, 2.90±0.95, 2.83±0.41 and 2.17±0.07 mg/ml) levels by graded doses of G. kola. There was dose dependent significant increase in the testosterone-cortisol ratio in the 1200mg/kg (0.63±0.07) and 1400mg/kg (0.76±0.04) treated groups compared with the untreated control (0.41±0.07). Overall, the anabolic action of G. kola indicated by weight gain is likely via its improvement of serum testosterone and antioxidants and mitigation of oxidative stress products in normal rats.', 'osifocharity@aauekpoma.edu.ng', 2022, 1, '1', '39-45', '', 'uploads/AAUJMR_V1_I1/paper 5. Osifo and Iyawe AAUJMR 1(1) 39-45.pdf'),
  ('Ethanol Leaf Extract of Acalypha Wilkesiana Modulates Streptozotocin-Induced Changes in Electrolytes and Kidney Functions of Diabetic Wistar Rats', 'Iyamu A.O., Njoku O.U., Ezeanyika L.A.', 'Diabetes is a metabolic disorder of insulin deficiency or resistance causing alterations to normal physiology of several organ/system. While we have recently documented ethanol leaf extract of Acalypha wilkesiana (ELEAW) to have hypoglycemic effect on the hyperglycemia induced in diabetic rats, there is a dearth of information on the renal physiology, hence the aim of this study. Diabetes was induced using 50mg/kg of freshly prepared streptozotocin (STZ) in 60 adult Wistar rats (170-200g). Thereafter, rats were divided into 3 groups (n = 5) and treated with distilled-water (10ml/kg; group A), glimepiride (0.1mg/kg; group B) and ELEAW (250mg/kg; group C). At baseline, 3 days diabetic induction, 7 and 14 days treatments, body weight and relative weight of the kidneys were determined. Blood was obtained for the estimations of serum creatinine and urea and plasma electrolytes (sodium, chloride, Potassium and bicarbonate). ANOVA was carried out (LSD as the post hoc test) and p <0.05 as significant on the data obtained using SPSS package (version 21). The results revealed increased relative weight of the kidneys, serum creatinine, urea and plasma bicarbonate levels but decreased plasma sodium, potassium and chloride levels in the diabetic untreated group. However, 7 and 14 days treatments with 250mg/kg ELEAW significantly reversed these alterations to near baseline and comparable levels with the standard drug (glimepiride) and control. In conclusion, ELEAW mitigates the diabetic- induced alterations in serum creatinine, urea and plasma electrolytes.', 'now_splash72@yahoo.com', 2022, 1, '1', '46-53', '', 'uploads/AAUJMR_V1_I1/paper 6. Iyamu et al AAUJMR 1(1) 46-53.pdf'),
  ('Drug Misuse and Consequences', 'Iyalomhe S.I., Osunde R.N., Omoregbe I., Edeawe I.O., Iyalomhe O.E., Iyalomhe G.B.S.', 'Globally, drug misuse and its attendant consequences have become the bedrock of social ills, thus constituting a universal challenge plaguing many nations and causing concern to both Governments and the people.Despite this ugly scenario, the solution to drug misuse has remained enigmatic. This review aims to educate and provide assistance in alleviating and reducing the challenges of drug misuse and its consequences, particularly in Nigeria.A manual literature and internet (Medline, HINARI, PubMed and other databases) search were conducted. It was found that commonly misused drugshave a notorious property of addictive potentials and hence, the unique ability to perpetuate their use by compromising rationality and wreaking havoc on the faculty of self-preservation. This causes myriad of health challenges which inevitably leads to disorder, dysfunction or destruction. Addictive substances induce pleasant/pleasurable states (euphoria in the initial phase) or relieve distress. Continued use induces adaptive changes in the central nervous system (CNS) that lead to tolerance, dependence, sensitization (reverse tolerance), craving and relapse with attendant adverse physical, mental, social, psychological and economic consequences. Strategies to control drug misuse include reduction of harm, psychotherapy, drug treatment and prevention initiatives. Realistic media literacy for youth is imperative and religious grouping activities are protective. Remediations of misuse are directed at restoring the total wellbeing of the individual and the family together with improved political and socioeconomic conditions as well as effective prevention strategies.', 'sarahiyalo@yahoo.com', 2022, 1, '1', '54-60', '', 'uploads/AAUJMR_V1_I1/Paper 7. Iyalomhe et al AAUJMR 1(1) 54-60.pdf'),
  ('Calcium and Endothelium Dependent Responses of Aortic Vascular Smooth Muscles in Pregnant Rats', 'Aigbiremolen A.A., Nwoke E.O., Odigie O.M., Edebiri O.E., Aloamaka C.P.', 'This study compared the calcium dependent responses of aortic ring vascular smooth muscle and the effect of de- endothelization in pregnant and nonpregnant rats. Twenty adult female Sprague Dawley rats of comparable weight (200±40g) were maintained under standard laboratory conditions in two groups (n=10) consisting of a control and test (pregnant) rats fed on normal rat chow. At day 17 to 19 of pregnancy, rats were sacrificed and the aortic blood vessels vascular smooth muscle isolated (with intact and removed endothelium) and processed in organ bath for EC 50 and maximum contraction strengths in different concentration of Ca 2+ physiological salt solution (PSS). The data were subjected to statistical analysis (t-test) at p<0.05. Pregnancy caused a significant increase in the aortic ring response to phenylephrine in both 1.6mM and 0.8mm Ca PSS with significant higher EC 50 in decreased Ca PSS. Removal of endothelium caused a significant decrease (p<0.05) in EC50 in both control and pregnant rats and was significantly higher in the pregnant rats compared to the control in both the endothelium intact and removed groups. Vascular smooth muscle contraction decreased significantly with decreasing Ca concentration and decreased significantly in pregnant rats compared to control in both 1.6mM (1909.50 ± 82.30 vs 1139.00 ± 103.40) and 0.8mM Ca PPS (1300.85 ± 57.36 vs 880.00 ± 25.95). However, removal of endothelium cause a non-significant increased (p>0.05) in the control (1909.5±82.3 vs 2012±63.4) but significant in the pregnant rats (1139.0±103.4 vs 2181±145.4). The findings therefore showed that Ca2+ concentration of PSS stimulates aortic vascular ring contractile responses to phenlyphrine. While pregnancy may attenuate this contractile response, the absent of endothelium may modulate it in pregnant rat but not in nonpregnant rat.', 'austineaigbiremolen@gmail.com', 2022, 1, '1', '61-67', '', 'uploads/AAUJMR_V1_I1/paper 8. Aigbiremolen et al AAUJMR 1(1) 61-67.pdf'),
  ('Acute Response to Ketogenic Diet Consumption on Lipid Biochemical Profiles of Wistar Rats', 'Oyakhire M.O., Shelu O.J., Otamere D.O., Imhantabhunu E.S.', 'Ketogenic diets have become popular for weight loss and in treatment of many diseases but there are still concerns regarding its impact on metabolic diseases and cardiovascular health. To obtain more comprehensive data on how ketogenic diet may affect the challenges of metabolic syndromes, this study aimed to evaluate the effects of short-term consumption of ketogenic diet on lipid biochemical profiles of healthy rat. Male Wistar rats weighing 150 ± 50 grams were randomly divided into 3 groups as follow: Control (fed standard rat chow; n = 10 rats), acute fed ketogenic diet (n = 5) and sub-acute fed ketogenic diet (n = 5). Ketogenic diet was made by adding 50% animal fat to the standard rat chow. Feeding lasted for 3 and 7 days for acute and sub-acute groups respectively. At the end of experiment, body weights were determined and blood samples obtained for lipid profile estimation using standard laboratory procedures. The results showed that ketogenic diet intake for 3 days cause a significant increase (p<0.05) in serum cholesterol and low density lipoprotein compared with the control diet. Conversely, there were significant decrease (p<0.05) in serum triglyceride (3 days ingestion), cholesterol (7 days ingestion) and high-density lipoprotein cholesterol (7 days ingestion) compared with the control. These findings indicate that ketogenic diet ingestion may predispose to metabolic syndromes and increase the risk of cardiovascular diseases via inhibitory impact on high density liproprotein cholesterol.', 'oyakhireosenimusa@aauekpoma.edu.ng', 2022, 1, '1', '68-73', '', 'uploads/AAUJMR_V1_I1/paper 9. Oyakhire et al AAUJMR 1(1) 68-73.pdf');
